assertions.check:
command -v node >/dev/null || { echo 'FAIL: node not found on PATH'; exit 1; }
d=$(mktemp -d) && trap 'rm -rf "$d"' 0 || exit 1
cat > "$d/zz_equiv.mjs" <<'EOF'
import { pathToFileURL } from 'node:url';
const { buildReport } = await import(pathToFileURL(process.argv[2]).href);
function base(rows) {
  const total = rows.filter((r) => r.active).map((r) => r.total).reduce((a, b) => a + b, 0);
  return { total, count: rows.filter((r) => r.active).length };
}
const outcome = (f, rows) => { try { const r = f(rows); return JSON.stringify([Object.is(r.total, -0) ? '-0' : String(r.total), typeof r.total, r.count, Object.keys(r)]); } catch (e) { return e.constructor.name; } };
const sparse = [{ active: true, total: 2 }, , { active: true, total: 3 }];
const cases = {
  empty: [],
  inactiveOnly: [{ active: false, total: 5 }, { active: 0, total: 7 }],
  mixed: Array.from({ length: 50 }, (_, i) => ({ active: i % 3 !== 0, total: i * 1.5 })),
  truthy: [{ active: 'yes', total: 1 }, { active: '', total: 2 }, { active: 1, total: 4 }, { total: 8 }],
  negZero: [{ active: true, total: -0 }],
  nan: [{ active: true, total: NaN }, { active: true, total: 1 }],
  strings: [{ active: true, total: '5' }, { active: true, total: 1 }],
  missingTotal: [{ active: true }, { active: true, total: 1 }],
  sparse,
  nullRow: [{ active: true, total: 1 }, null],
};
let bad = 0;
for (const [name, rows] of Object.entries(cases)) {
  const want = outcome(base, rows), got = outcome(buildReport, rows);
  if (want !== got) { bad++; console.log(`MISMATCH ${name}: got ${got}, want ${want}`); }
}
console.log(`equivalence cases=${Object.keys(cases).length} mismatches=${bad}`);
process.exit(bad ? 1 : 0);
EOF
node "$d/zz_equiv.mjs" "$PWD/report/report.mjs"

command -v node >/dev/null || { echo 'FAIL: node not found on PATH'; exit 1; }
d=$(mktemp -d) && trap 'rm -rf "$d"' 0 || exit 1
cat > "$d/zz_gc.mjs" <<'EOF'
import { pathToFileURL } from 'node:url';
const { buildReport } = await import(pathToFileURL(process.argv[3]).href);
function base(rows) {
  const total = rows.filter((r) => r.active).map((r) => r.total).reduce((a, b) => a + b, 0);
  return { total, count: rows.filter((r) => r.active).length };
}
const f = process.argv[2] === 'base' ? base : buildReport;
const rows = Array.from({ length: 1000 }, (_, i) => ({ id: i, active: i % 3 !== 0, total: (i * 37) % 1000 }));
let sink = 0;
for (let i = 0; i < 50000; i++) sink += f(rows).count;
if (sink !== 50000 * 666) { console.log('wrong count'); process.exit(1); }
EOF
b=$(node --trace-gc "$d/zz_gc.mjs" base "$PWD/report/report.mjs" | grep -c Scavenge)
c=$(node --trace-gc "$d/zz_gc.mjs" cand "$PWD/report/report.mjs" | grep -c Scavenge)
echo "scavenges over 50000 calls: baseline $b, candidate $c"
[ "$b" -gt 0 ] && [ $((c * 4)) -le "$b" ] || { echo 'FAIL: candidate still triggers more than a quarter of the baseline scavenges'; exit 1; }

grep -Eiq '^FROM +(docker\.io/)?oven/bun' app/Dockerfile || { echo 'FAIL: Dockerfile base image is not oven/bun'; exit 1; }
if grep -Eq 'npm (ci|install)|CMD \[?"?node"?' app/Dockerfile; then echo 'FAIL: Dockerfile still installs or runs with npm/node'; exit 1; fi
grep -Eq '"start": *"bun ' app/package.json || { echo 'FAIL: start script does not run bun'; exit 1; }
